class Data3RepositoryImpl @Inject constructor(
    private val remoteDataSource: Data3RemoteDataSource,
    private val localDataSource: Data3LocalDataSource
) : Data3Repository {

    override suspend fun getData3s(): Result<List<Data3>> = try {
        val users = remoteDataSource.fetchData3s()
        localDataSource.saveData3s(users)
        Result.success(users)
    } catch (e: Exception) {
        val cachedData3s = localDataSource.getData3s()
        if (cachedData3s.isNotEmpty()) {
            Result.success(cachedData3s)
        } else {
            Result.failure(e)
        }
    }
}

