class ApiClient {

    fun fetchData4s(): List<Data4> {
        val response = httpClient.get("https://api.example.com/users")
        val json = response.body()
        return parseData4s(json)
    }

    fun parseData4s(json: String): List<Data4> {
        val users = mutableListOf<Data4>()
        val jsonArray = JSONArray(json)
        for (i in 0 until jsonArray.length()) {
            val obj = jsonArray.getJSONObject(i)
            users.add(Data4(
                obj.getString("id"),
                obj.getString("name"),
                obj.getString("email")
            ))
        }
        return users
    }
}

