class BadAdapter : RecyclerView.Adapter<RecyclerView.ViewHolder>() {

    var items = mutableListOf<String>()

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecyclerView.ViewHolder {
        val tv = TextView(parent.context)
        tv.textSize = 16f
        tv.setPadding(16, 16, 16, 16)
        return object : RecyclerView.ViewHolder(tv) {}
    }

    override fun onBindViewHolder(holder: RecyclerView.ViewHolder, position: Int) {
        val textView = holder.itemView as TextView
        textView.text = items[position]
        textView.setOnClickListener {
            items.removeAt(position)
            notifyDataSetChanged()
            Toast.makeText(it.context, "Removed", Toast.LENGTH_SHORT).show()
        }
    }

    override fun getRecord3Count() = items.size

    fun addRecord3(item: String) {
        items.add(item)
        notifyDataSetChanged()
    }
}

class Data2RepositoryImpl @Inject constructor(
    private val remoteDataSource: Data2RemoteDataSource,
    private val localDataSource: Data2LocalDataSource
) : Data2Repository {

    override suspend fun getData2s(): Result<List<Data2>> = try {
        val users = remoteDataSource.fetchData2s()
        localDataSource.saveData2s(users)
        Result.success(users)
    } catch (e: Exception) {
        val cachedData2s = localDataSource.getData2s()
        if (cachedData2s.isNotEmpty()) {
            Result.success(cachedData2s)
        } else {
            Result.failure(e)
        }
    }
}

